"q": "Sobre a definição das Anormalidades Pulmonares Intersticiais (API), conhecidas na literatura inglesa pelo termo Interstitial Lung Abnormalities (ILA), segundo a sociedade Fleischner, assinale a alternativa correta.",
"alts": [
"A API é definida como achado incidental de alterações não decúbito dependente, incluindo vidro fosco, reticulado, distorção pulmonar, bronquiectasias de tração, faveolamento e cistos não enfisematosos, acometendo pelo menos 5% de uma zona pulmonar, em pacientes em que não se suspeita de doença pulmonar intersticial.",
"A API deve acometer menos de 5% do parênquima pulmonar de uma das zonas pulmonares (superior, média ou inferior, demarcadas pelo nível do arco aórtico inferior e da veia pulmonar inferior direita) para ser diagnosticada.",
"Segundo a sociedade Fleischner, a fibrose pulmonar focal paraespinhal, relacionada a osteofitos da coluna torácica, pode ser considerada uma API.",
"Achados relacionados a aspiração como por exemplo opacidades em vidro fosco, opacidades centrolobulares e em árvore em brotamento, podem ser consideradas API.",
"A API pode ser subcategorizada segundo a sua localização no parênquima pulmonar como subpleural não fibrótica, subpleural fibrótica, central não fibrótica e central fibrótica."
],
