"coment": "API (ILA): achados intersticiais INCIDENTAIS não gravitacionais — vidro fosco, reticulado, distorção, bronquiectasias de tração, faveolamento, cistos não enfisematosos — acometendo ≥5% de uma zona pulmonar em paciente SEM suspeita de doença intersticial (definição Fleischner) — alternativa A. Fibrose paraespinhal por osteófito, aspiração e achados dependentes são EXCLUÍDOS; a subcategoria é subpleural/não subpleural (fibrótica ou não).",
