"q": "Sobre bronquiolites, assinale alternativa correta.",
"alts": [
"Bronquiolites infecciosas agudas em crianças são caracterizadas tomograficamente por nódulos centrolobulares ramificados do tipo \"árvore em brotamento\" e tem como agentes etiológicos mais comuns o pneumococo e o aspergilus.",
"A bronquiolite respiratória é uma condição caracterizada histologicamente por acúmulo de eosinófilos no lúmen dos bronquíolos respiratórios e nos alvéolos adjacentes. É comum em pessoas com exposição ao tabaco e ao mofo.",
"A principal manifestação tomográfica da bronquiolite obliterativa ou constritiva é a presença de áreas definidas de redução da atenuação pulmonar e da vascularização na aquisição em inspiração e aprisionamento aéreo nas imagens em expiração. Algumas das condições associadas são pacientes transplantados pulmonares, artrite reumatoide e doença inflamatória intestinal.",
"Hiperplasia difusa de células neuroendócrinas é uma rara condição caracterizada por proliferação de células neuroendócrinas ao longo da membrana basal e tem como características de imagem a presença de pequenos nódulos pulmonares associado a bronquiectasias císticas e dilatação da traqueia.",
"A bronquiolite folicular é uma condição caracterizada histologicamente por discretos focos hiperplásicos de tecido linfoide ao longo dos feixes broncovasculares e podem estar presentes também nos septos interlobulares e pleura visceral. É um achado frequente pulmonar no contexto de neoplasia folicular da tireoide e na retocolite ulcerativa."
],
